    link:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10.3 13.7a4.4 4.4 0 0 0 6.2 0l2.2-2.2a4.4 4.4 0 0 0-6.2-6.2l-1.3 1.3"/><path d="M13.7 10.3a4.4 4.4 0 0 0-6.2 0l-2.2 2.2a4.4 4.4 0 0 0 6.2 6.2l1.3-1.3"/></svg>',
